grant create on schema api,app_private,finance_private to git_tutor_commands;
create table finance_private.transfer_reversal_accounts(reversal_id uuid primary key references finance_private.transfer_reversals(id),unapplied_cap_minor bigint not null check(unapplied_cap_minor>=0));
create table finance_private.credit_loss_attributions(id uuid primary key default gen_random_uuid(),credit_lot_id uuid not null references finance_private.customer_credit_lots(id),reversal_id uuid not null references finance_private.transfer_reversals(id),resolution_id uuid not null references finance_private.transfer_reversal_resolutions(id) deferrable initially deferred,amount_minor bigint not null check(amount_minor>0),command_id uuid not null,created_at timestamptz not null default now());
do $$declare n text;begin foreach n in array array['transfer_reversal_accounts','credit_loss_attributions'] loop execute format('alter table finance_private.%I enable row level security',n);execute format('create policy commands_access on finance_private.%I to git_tutor_commands using(true) with check(true)',n);execute format('grant select,insert on finance_private.%I to git_tutor_commands',n);execute format('revoke all on finance_private.%I from public,anon,authenticated,service_role,git_tutor_worker',n);execute format('create trigger immutable_source before update or delete on finance_private.%I for each row execute function app_private.reject_immutable_change()',n);end loop;end $$;
create or replace function finance_private.finance_credit_available(p_lot_id uuid) returns bigint language sql stable security definer set search_path='' as $$select(l.original_minor-coalesce((select sum(r.amount_minor) from finance_private.credit_reservations r where r.credit_lot_id=l.id and r.state in('reserved','consumed')),0)-coalesce((select sum(w.amount_minor) from finance_private.credit_loss_attributions w where w.credit_lot_id=l.id),0))::bigint from finance_private.customer_credit_lots l where l.id=p_lot_id$$;
create function app_private.payment_reversal_command(p_name text,p_input jsonb,p_key text) returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_variable
declare actor uuid:=app_private.require_actor();t finance_private.incoming_transfers%rowtype;rv finance_private.transfer_reversals%rowtype;context jsonb;scope jsonb;balance jsonb;result jsonb;posting uuid;reversal uuid;resolution uuid:=gen_random_uuid();exception_id uuid;amount bigint;remaining numeric;unapplied numeric;cap numeric;allocated numeric;item jsonb;lot record;take bigint;source_ids uuid[]:='{}';begin
 perform app_private.require_role(actor,'admin');if p_name='record_transfer_reversal' then select * into t from finance_private.incoming_transfers where id=(p_input->>'transfer_id')::uuid;else select * into rv from finance_private.transfer_reversals where id=(p_input->>'reversal_id')::uuid;select * into t from finance_private.incoming_transfers where id=rv.transfer_id;end if;if t.id is null then raise exception 'NOT_FOUND';end if;
 context:=app_private.booking_begin(actor,p_name,p_input,p_key);if context->'replay_result'<>'null'::jsonb then return context->'replay_result';end if;
 scope:=finance_private.finance_discover_scope('{}',array[t.id],'{}','{}');perform app_private.booking_lock_financial_scope(scope);perform app_private.require_role(actor,'admin');select * into t from finance_private.incoming_transfers where id=t.id;
 if t.version is distinct from(p_input->>'expected_version')::int then raise exception 'VERSION_CONFLICT';end if;
 if p_name='record_transfer_reversal' then
  amount:=(p_input->>'amount_minor')::bigint;if amount is null or amount not between 1 and 9007199254740991 or length(btrim(coalesce(p_input->>'external_reversal_id',''))) not between 1 and 200 then raise exception 'VALIDATION_ERROR';end if;
  if (p_input->>'effective_at')::timestamptz is null or not isfinite((p_input->>'effective_at')::timestamptz) or(p_input->>'effective_at')::timestamptz<timestamptz '0001-01-01 00:00:00+00' or(p_input->>'effective_at')::timestamptz>now() then raise exception 'INVALID_TIME';end if;
  perform app_private.payment_assert_file((p_input->>'evidence_file_id')::uuid,'transfer_reversal','transfer',t.id);balance:=finance_private.finance_transfer_balance(t.id);
  if amount>(balance->>'gross_settled_minor')::numeric-(balance->>'reversed_minor')::numeric then raise exception 'AMOUNT_OUT_OF_RANGE';end if;
  if exists(select 1 from finance_private.transfer_reversals old_reversal where old_reversal.receiving_account_id=t.receiving_account_id and old_reversal.channel=t.channel and old_reversal.external_reversal_id=btrim(p_input->>'external_reversal_id')) then raise exception 'DUPLICATE_TRANSFER';end if;
  cap:=least(amount,greatest(0,(balance->>'unapplied_signed_minor')::numeric-coalesce((select sum(cr.amount_minor) from finance_private.credit_reservations cr join finance_private.customer_credit_lots cl on cl.id=cr.credit_lot_id where cl.transfer_id=t.id and cr.state='reserved'),0)));
  reversal:=gen_random_uuid();posting:=finance_private.finance_post_balanced('bank-reversal:'||reversal,'transfer_reversed',reversal,t.currency,(p_input->>'effective_at')::timestamptz,jsonb_build_array(jsonb_build_object('account_code','unapplied_customer_funds','transfer_id',t.id,'reversal_id',reversal,'signed_minor',amount),jsonb_build_object('account_code','channel_cash','transfer_id',t.id,'reversal_id',reversal,'signed_minor',-amount)),context);
  insert into finance_private.transfer_reversals(id,transfer_id,receiving_account_id,channel,external_reversal_id,amount_minor,evidence_file_id,ledger_transaction_id,actor_account_id,command_id,effective_at) values(reversal,t.id,t.receiving_account_id,t.channel,btrim(p_input->>'external_reversal_id'),amount,(p_input->>'evidence_file_id')::uuid,posting,actor,(context->>'command_id')::uuid,(p_input->>'effective_at')::timestamptz);
  insert into finance_private.transfer_reversal_accounts values(reversal,cap);
  update finance_private.incoming_transfers set state=case when(balance->>'reversed_minor')::numeric+amount=(balance->>'gross_settled_minor')::numeric then 'reversed' else state end,version=version+1,updated_at=now() where id=t.id returning * into t;
  balance:=finance_private.finance_transfer_balance(t.id);
  insert into app_private.reconciliation_exceptions(source_type,source_id,kind,owner_id,signed_exposure_minor,currency,reason) values('transfer',t.id,'transfer_reversal',actor,-(balance->>'recovery_exposure_minor')::bigint,t.currency,'Assign the evidenced bank reversal to its original sources') returning id into exception_id;
  perform app_private.package_mark_financing_hold('transfer',t.id,context);
  result:=jsonb_build_object('reversal_id',reversal,'reconciliation_exception_id',exception_id);
 else
  if jsonb_typeof(p_input->'allocations')<>'array' or jsonb_array_length(p_input->'allocations')>100 or length(btrim(coalesce(p_input->>'reason',''))) not between 1 and 2000 then raise exception 'VALIDATION_ERROR';end if;
  unapplied:=(p_input->>'unapplied_minor')::numeric;if unapplied is null or unapplied<0 or unapplied>9007199254740991 then raise exception 'AMOUNT_OUT_OF_RANGE';end if;allocated:=0;
  for item in select value from jsonb_array_elements(p_input->'allocations') loop
   if jsonb_typeof(item)<>'object' or item-array['allocation_id','amount_minor']<>'{}'::jsonb or(item->>'amount_minor')::numeric not between 1 and 9007199254740991 or(item->>'amount_minor')::numeric<>trunc((item->>'amount_minor')::numeric) or(item->>'allocation_id')::uuid=any(source_ids) then raise exception 'VALIDATION_ERROR';end if;
   source_ids:=array_append(source_ids,(item->>'allocation_id')::uuid);allocated:=allocated+(item->>'amount_minor')::numeric;
  end loop;
  select rv.amount_minor-coalesce(sum(r.unapplied_minor+(select coalesce(sum((v->>'amount_minor')::numeric),0) from jsonb_array_elements(r.allocations)v)),0) into remaining from finance_private.transfer_reversal_resolutions r where r.reversal_id=rv.id;
  if unapplied+allocated<=0 or unapplied+allocated>remaining then raise exception 'AMOUNT_OUT_OF_RANGE';end if;
  select a.unapplied_cap_minor-coalesce((select sum(r.unapplied_minor) from finance_private.transfer_reversal_resolutions r where r.reversal_id=rv.id),0) into cap from finance_private.transfer_reversal_accounts a where a.reversal_id=rv.id;
  if unapplied>cap then raise exception 'AMOUNT_OUT_OF_RANGE';end if;
  for item in select value from jsonb_array_elements(p_input->'allocations') order by value->>'allocation_id' loop
   if not exists(select 1 from finance_private.payment_allocations a where a.id=(item->>'allocation_id')::uuid and a.transfer_id=t.id) then raise exception 'FORBIDDEN';end if;
   perform finance_private.finance_reverse_allocation((item->>'allocation_id')::uuid,(item->>'amount_minor')::bigint,p_input->>'reason','bank_reversal',rv.id,context,'bank-loss:'||(item->>'allocation_id'));
  end loop;
  cap:=unapplied;
  for lot in select l.id,finance_private.finance_credit_available(l.id) available from finance_private.customer_credit_lots l where l.transfer_id=t.id order by l.created_at,l.id loop
   exit when cap=0;take:=least(cap,lot.available);if take<=0 then continue;end if;insert into finance_private.credit_loss_attributions(credit_lot_id,reversal_id,resolution_id,amount_minor,command_id) values(lot.id,rv.id,resolution,take,(context->>'command_id')::uuid);update finance_private.credit_lot_accounts set version=version+1,updated_at=now() where credit_lot_id=lot.id;cap:=cap-take;
  end loop;if cap<>0 then raise exception 'INSUFFICIENT_FUNDS';end if;
  insert into finance_private.transfer_reversal_resolutions(id,reversal_id,allocations,unapplied_minor,reason,actor_account_id,command_id) values(resolution,rv.id,p_input->'allocations',unapplied,p_input->>'reason',actor,(context->>'command_id')::uuid);
  remaining:=remaining-unapplied-allocated;update finance_private.incoming_transfers set version=version+1,updated_at=now() where id=t.id returning * into t;
  balance:=finance_private.finance_transfer_balance(t.id);
  if remaining=0 and(balance->>'recovery_exposure_minor')::numeric=0 then update app_private.reconciliation_exceptions set state='resolved',resolution_id=resolution,version=version+1,updated_at=now() where source_type='transfer' and source_id=t.id and kind='transfer_reversal' and state='open' and not exists(select 1 from finance_private.transfer_reversals x where x.transfer_id=t.id and x.amount_minor>(select coalesce(sum(y.unapplied_minor+(select coalesce(sum((v->>'amount_minor')::numeric),0) from jsonb_array_elements(y.allocations)v)),0) from finance_private.transfer_reversal_resolutions y where y.reversal_id=x.id));end if;
  select id into exception_id from app_private.reconciliation_exceptions where source_type='transfer' and source_id=t.id and state='open' order by created_at,id limit 1;
  result:=jsonb_build_object('resolution_id',resolution,'remaining_unresolved_minor',remaining,'reconciliation_exception_id',exception_id);
 end if;
 return app_private.booking_finish(context,t.id,t.version,result,p_name,jsonb_build_object('transfer_id',t.id));
end $$;
create function api.record_transfer_reversal(p_transfer_id uuid,p_external_reversal_id text,p_amount_minor bigint,p_effective_at timestamptz,p_evidence_file_id uuid,p_expected_version integer,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$select app_private.payment_reversal_command('record_transfer_reversal',jsonb_build_object('transfer_id',p_transfer_id,'external_reversal_id',p_external_reversal_id,'amount_minor',p_amount_minor,'effective_at',p_effective_at,'evidence_file_id',p_evidence_file_id,'expected_version',p_expected_version),p_idempotency_key)$$;
create function api.resolve_transfer_reversal(p_reversal_id uuid,p_allocations jsonb,p_unapplied_minor bigint,p_reason text,p_expected_version integer,p_idempotency_key text) returns jsonb language sql security definer set search_path='' as $$select app_private.payment_reversal_command('resolve_transfer_reversal',jsonb_build_object('reversal_id',p_reversal_id,'allocations',p_allocations,'unapplied_minor',p_unapplied_minor,'reason',p_reason,'expected_version',p_expected_version),p_idempotency_key)$$;
do $$declare f record;begin for f in select p.oid::regprocedure::text signature,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where(n.nspname='app_private' and p.proname='payment_reversal_command') or(n.nspname='api' and p.proname in('record_transfer_reversal','resolve_transfer_reversal')) loop execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api' then execute format('grant execute on function %s to authenticated',f.signature);end if;end loop;end $$;
revoke create on schema api,app_private,finance_private from git_tutor_commands;
notify pgrst,'reload schema';
